#!/usr/bin/env python3
"""Generates db/seed.sql: the starting content for the Coffee Time site.

Source: the Wix site (playcoffeetime.com) as it stood on 2026-10-24, copied page by page. Every
statement is INSERT OR IGNORE, so re-running never overwrites edits made in HQ. After launch, change
words in HQ, not here.

House rule: no em dashes anywhere (the Wix copy had a few; they became commas, colons or periods).
Links inside copy are written as [text](url); **double stars** make bold.
"""
from pathlib import Path

OUT = Path(__file__).with_name("seed.sql")
lines: list[str] = ["-- GENERATED by db/make-seed.py. Do not edit by hand.", ""]


def q(v) -> str:
    if v is None:
        return "NULL"
    if isinstance(v, (int, float)):
        return str(v)
    s = str(v)
    assert "—" not in s, f"em dash in seed: {s[:60]}"
    return "'" + s.replace("'", "''") + "'"


def ins(table: str, row: dict):
    cols = ",".join(row)
    vals = ",".join(q(v) for v in row.values())
    lines.append(f"INSERT OR IGNORE INTO {table}({cols}) VALUES({vals});")


